import json, os, subprocess, platform
from pathlib import Path
from openpyxl import load_workbook

filename = 'sales_data.xlsx'
# Setup LibreOffice macro (same as recalc.py)
if platform.system() == 'Darwin':
    macro_dir = os.path.expanduser('~/Library/Application Support/LibreOffice/4/user/basic/Standard')
else:
    macro_dir = os.path.expanduser('~/.config/libreoffice/4/user/basic/Standard')
macro_file = os.path.join(macro_dir, 'Module1.xba')
if not (os.path.exists(macro_file) and 'RecalculateAndSave' in open(macro_file).read()):
    if not os.path.exists(macro_dir):
        subprocess.run(['soffice', '--headless', '--terminate_after_init'], capture_output=True, timeout=10)
        os.makedirs(macro_dir, exist_ok=True)
    macro_content = '<?xml version="1.0" encoding="UTF-8"?>\n<!DOCTYPE script:module PUBLIC "-//OpenOffice.org//DTD OfficeDocument 1.0//EN" "module.dtd">\n<script:module xmlns:script="http://openoffice.org/2000/script" script:name="Module1" script:language="StarBasic">\n    Sub RecalculateAndSave()\n      ThisComponent.calculateAll()\n      ThisComponent.store()\n      ThisComponent.close(True)\n    End Sub\n</script:module>'
    with open(macro_file, 'w') as f:
        f.write(macro_content)

abs_path = str(Path(filename).absolute())
cmd = ['soffice', '--headless', '--norestore',
       'vnd.sun.star.script:Standard.Module1.RecalculateAndSave?language=Basic&location=application', abs_path]
if platform.system() == 'Linux':
    cmd = ['timeout', '30'] + cmd
result = subprocess.run(cmd, capture_output=True, text=True)
print('soffice returncode:', result.returncode)
if result.returncode != 0 and result.returncode != 124:
    print('stderr:', result.stderr[:500])

# Scan all cells for Excel errors (data_only)
wb = load_workbook(filename, data_only=True)
excel_errors = ['#VALUE!', '#DIV/0!', '#REF!', '#NAME?', '#NULL!', '#NUM!', '#N/A']
error_details = {e: [] for e in excel_errors}
total_errors = 0
for sn in wb.sheetnames:
    ws = wb[sn]
    for row in ws.iter_rows():
        for cell in row:
            if cell.value is not None and isinstance(cell.value, str):
                for e in excel_errors:
                    if e in cell.value:
                        error_details[e].append(f"{sn}!{cell.coordinate}")
                        total_errors += 1
                        break
wb.close()

wb2 = load_workbook(filename, data_only=False)
formula_count = 0
for sn in wb2.sheetnames:
    ws = wb2[sn]
    for row in ws.iter_rows():
        for cell in row:
            if cell.value and isinstance(cell.value, str) and cell.value.startswith('='):
                formula_count += 1
wb2.close()

out = {'status': 'success' if total_errors == 0 else 'errors_found', 'total_errors': total_errors, 'total_formulas': formula_count}
out['error_summary'] = {k: {'count': len(v), 'locations': v[:20]} for k, v in error_details.items() if v}
print(json.dumps(out, indent=2))
EOF
